int Pick(float[] prefix) {                       // prefixes built in advance
    float r = UnityEngine.Random.Range(0f, prefix[prefix.Length - 1]); // [0, total], both inclusive
    int lo = 0, hi = prefix.Length - 1;             // r == total → the last item
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (prefix[mid] <= r) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

