// a pick from an alias table: prob[i] in [0, 1], alias[i] is column i's neighbour
int PickAlias(float[] prob, int[] alias, System.Random rnd) {
    int i = rnd.Next(prob.Length);                     // a uniform column
    return rnd.NextDouble() < prob[i] ? i : alias[i];  // a coin flip inside it
}
